const sqlMap = {
  occupancy:`SELECT\n  ROUND(SUM(CASE WHEN c.status = 'ACTIVE' THEN c.rent_area ELSE 0 END)\n    / NULLIF(SUM(b.rentable_area), 0) * 100, 1) AS occupancy_rate,\n  DATE_FORMAT(CURRENT_DATE, '%Y-%m-%d') AS stat_date\nFROM building b\nLEFT JOIN contract c ON c.building_id = b.id\n  AND CURRENT_DATE BETWEEN c.start_date AND c.end_date\nWHERE b.deleted = 0;`,
  contract:`SELECT ROUND(SUM(c.total_amount), 2) AS contract_amount\nFROM contract c\nWHERE c.status = 'ACTIVE' AND c.deleted = 0;`,
  collection:`SELECT DATE_FORMAT(p.payment_date, '%Y-%m') AS stat_month,\n  ROUND(SUM(p.paid_amount) / NULLIF(SUM(p.receivable_amount),0) * 100, 1) AS collection_rate\nFROM payment p\nWHERE p.status IN ('PAID','PARTIAL')\nGROUP BY DATE_FORMAT(p.payment_date, '%Y-%m')\nORDER BY stat_month;`,
  arrears:`SELECT b.name AS building_name, SUM(p.receivable_amount - p.paid_amount) AS arrears_amount\nFROM payment p JOIN contract c ON p.contract_id = c.id\nJOIN building b ON c.building_id = b.id\nWHERE p.due_date < CURRENT_DATE AND p.paid_amount < p.receivable_amount\nGROUP BY b.id, b.name ORDER BY arrears_amount DESC;`,
  enterprise:`SELECT DATE_FORMAT(e.created_at, '%Y-%m') AS stat_month, COUNT(*) AS enterprise_count\nFROM enterprise e WHERE e.deleted = 0\nGROUP BY DATE_FORMAT(e.created_at, '%Y-%m') ORDER BY stat_month;`,
  conversion:`SELECT COUNT(DISTINCT CASE WHEN l.status = 'SIGNED' THEN l.id END) / NULLIF(COUNT(DISTINCT l.id),0) * 100 AS conversion_rate\nFROM investment_lead l WHERE l.deleted = 0;`
};

const $=(s,el=document)=>el.querySelector(s), $$=(s,el=document)=>[...el.querySelectorAll(s)];
const clone=x=>JSON.parse(JSON.stringify(x));
