let state={metrics:[],versions:[],references:[],activeVersion:null,schemaReady:false,schemaAnalysis:null,databaseMode:'offline',databaseMeta:null,metricSchemaContext:{},generated:false,dashboardDesign:null,dashboardRuntimeData:{},previewDataMode:'offline',dataRequirements:[],dataLogic:{},dashboardStyle:'简约风格',styleNotes:'',authMode:'deepseek',deepseekModel:'deepseek-flash',apiBaseUrl:'https://api.example.com/v1',customModel:'your-model-id',endpoint:'/api/generate-dashboard'};
