function workflow(){
  const businessContext=$('#businessContext').value.trim(),promptText=$('#promptText').value.trim();
  const ready={brief:$('#projectName').value.trim().length>2&&Boolean(businessContext),data:state.schemaReady,prompt:Boolean(promptText),metrics:state.generated&&state.metrics.length>0};
  [['#briefStatus',ready.brief,'已完成','待填写'],['#dataStatus',ready.data,'已导入','待提供'],['#promptStatus',ready.prompt,'已确认','待确认'],['#metricStatus',ready.metrics,`${state.metrics.length} 项指标`,'等待生成']].forEach(([id,ok,yes,no])=>{const el=$(id);el.textContent=ok?yes:no;el.classList.toggle('complete',ok)});
  const count=Object.values(ready).filter(Boolean).length;
  const hasBusinessScene=Boolean(businessContext),unlocked=hasBusinessScene;
  $('.progress-ring span').textContent=`${count*25}%`;$('.progress-ring .value').style.strokeDashoffset=113-(113*count/4);
  const p=$('#previewBtn');p.disabled=!unlocked;p.classList.toggle('locked',!unlocked);p.classList.toggle('ready',unlocked);p.textContent=unlocked?(state.dashboardDesign?'▶ 预览已生成看板':`▶ 预览概念看板（大纲 ${count}/4）`):'⌁ 填写业务场景后预览';
  $('#regenerateBtn').disabled=!state.generated;const dashboardBtn=$('#generateDashboardBtn');if(dashboardBtn){dashboardBtn.disabled=!ready.metrics;dashboardBtn.textContent=state.dashboardDesign?'✦ 重新生成看板':'✦ 生成看板';$('#dashboardStatus').textContent=state.dashboardDesign?'已保存 DeepSeek 生成的看板，预览不会再次调用模型':'指标大纲优先，数据结构与业务场景作为补充参考'}return {ready,unlocked};
}

function renderMetrics(){
  const target=$('#metricList');
  target.innerHTML=state.metrics.length?state.metrics.map(m=>`<article class="metric-card"><span class="metric-icon">${m.icon||'◇'}</span><div><b>${m.name}</b><small>${m.desc}</small></div><em>${m.chart}</em><span class="metric-tools"><button data-edit="${m.id}" title="编辑">✎</button><button class="danger" data-delete="${m.id}" title="删除">×</button></span></article>`).join(''):'<div style="grid-column:1/-1;text-align:center;padding:28px;color:#8b958f;font-size:9px">完成前 3 步后生成指标，也可以手动添加</div>';
  $('#metricNavCount').textContent=`${state.metrics.length} 项`;const activeVersion=state.versions.find(v=>v.id===state.activeVersion);$('#activePlanLabel').textContent=activeVersion?`当前：${activeVersion.label}`:'当前：未保存的指标方案';
  $('#metricNav').innerHTML=state.metrics.map(m=>{const req=getRequirement(m.id),logic=state.dataLogic?.[m.id],required=req?.parameters?.filter(p=>p.required)||[],mapped=required.length&&required.every(p=>logic?.mappings?.[p.key]);const label=mapped?'已映射':req?'待映射':'待生成';return `<button class="${m.id===activeMetric?'active':''}" data-metric-nav="${m.id}">${m.icon||'◇'} ${esc(m.name)}<span class="${mapped?'mapped':'pending'}">${label}</span></button>`}).join('')||'<small style="color:#87918c">当前方案尚无指标</small>';
  $$('[data-edit]').forEach(b=>b.onclick=()=>openMetric(b.dataset.edit));$$('[data-delete]').forEach(b=>b.onclick=()=>deleteMetric(b.dataset.delete));$$('[data-metric-nav]').forEach(b=>b.onclick=()=>selectMetric(b.dataset.metricNav));workflow();
}

function renderVersions(){const el=$('#versionStrip');if(!state.versions.length){el.innerHTML='<span>尚未生成版本</span>';return}el.innerHTML='<span>方案版本</span>'+state.versions.map(v=>`<span class="version-item"><button class="version-select ${v.id===state.activeVersion?'active':''}" data-version="${v.id}">${esc(v.label)}</button><button class="version-delete" data-delete-version="${v.id}" title="删除版本">×</button></span>`).join('');$$('[data-version]').forEach(b=>b.onclick=()=>loadVersion(b.dataset.version));$$('[data-delete-version]').forEach(b=>b.onclick=()=>deleteVersion(b.dataset.deleteVersion))}
function deleteVersion(id){const version=state.versions.find(v=>v.id===id);if(!version)return;state.versions=state.versions.filter(v=>v.id!==id);if(state.activeVersion===id){const next=state.versions.at(-1);if(next){state.activeVersion=next.id;state.metrics=clone(next.metrics);state.generated=true;activeMetric=state.metrics[0]?.id||''}else{state.activeVersion=null;state.metrics=[];state.generated=false;activeMetric=''}state.dashboardDesign=null;state.dataRequirements=[];state.dataLogic={}}save();renderVersions();renderMetrics();renderDashboard();renderDataWorkspace();toast(`已删除 ${version.label}`)}
function getRequirement(id){const requirements=state.dataRequirements?.length?state.dataRequirements:(state.dashboardDesign?.dataRequirements||[]);return requirements.find(item=>item.metricId===id)}
function getLogic(id){state.dataLogic=state.dataLogic||{};return state.dataLogic[id]||(state.dataLogic[id]={mappings:{},sql:'',dialect:'SQL Server',manual:false,linkUrl:'',validation:null})}
function availableFields(metricId=activeMetric){const onlineTables=state.metricSchemaContext?.[metricId]?.tables||[],offlineTables=state.schemaAnalysis?.tables||[],tables=[...offlineTables,...onlineTables].filter((table,index,list)=>list.findIndex(item=>item.name===table.name)===index);return tables.flatMap(table=>(table.fields||[]).map(field=>({value:`${table.name}.${field.name}`,table:table.businessName||table.name,name:field.name,type:field.type||field.dataType||'',meaning:field.meaning||field.description||''})))}
function sqlFromTemplate(requirement,logic){const template=requirement?.sqlTemplate||`-- DeepSeek 尚未返回 ${requirement?.metricName||'该指标'} 的 SQL 模板`,mapped=Object.values(logic.mappings||{}).filter(Boolean),sourceTable=String(mapped[0]||'').split('.')[0];return template.replace(/\{\{\s*table:([\w.-]+)\s*\}\}/g,(all,key)=>String(logic.mappings?.[key]||'').split('.')[0]||all).replace(/\{\{\s*source_table\s*\}\}/g,sourceTable||'{{source_table}}').replace(/\{\{\s*([\w.-]+)\s*\}\}/g,(all,key)=>logic.mappings?.[key]||all)}
function renderDataWorkspace(){const metric=state.metrics.find(m=>m.id===activeMetric)||state.metrics[0];if(!metric){$('#sqlMetricTitle').textContent='当前方案没有指标';$('#parameterMappings').innerHTML='<div class="empty-mapping">请先在第一步生成或选择指标方案</div>';$('#sqlEditor').value='';$('#metricLinkUrl').value='';$('#sqlValidation').textContent='等待验证';$('#sqlValidationIcon').textContent='○';return}activeMetric=metric.id;const requirement=getRequirement(metric.id),logic=getLogic(metric.id),parameters=requirement?.parameters||[],fields=availableFields();$('#sqlMetricTitle').textContent=metric.name;$('#dataMetricSummary').innerHTML=requirement?`<div><b>${esc(metric.desc)}</b><span>统计粒度：${esc(requirement.grain||'待确认')} · 聚合：${esc(requirement.aggregation||'待确认')}</span></div><em>${parameters.length} 个参数</em>`:`<div><b>${esc(metric.desc)}</b><span>重新生成看板后，DeepSeek 会同时返回该指标的参数契约</span></div><em>等待生成</em>`;$('#parameterMappings').innerHTML=parameters.length?parameters.map(parameter=>`<label class="parameter-map-row"><span><b>${esc(parameter.label)}${parameter.required?' *':''}</b><small><i class="parameter-role">${esc(parameter.role)}</i>${esc(parameter.description||parameter.dataType)}</small></span><select data-parameter="${esc(parameter.key)}"><option value="">选择表字段…</option>${fields.map(field=>`<option value="${esc(field.value)}" ${logic.mappings?.[parameter.key]===field.value?'selected':''}>${esc(field.table)} · ${esc(field.name)}${field.type?`（${esc(field.type)}）`:''}</option>`).join('')}</select></label>`).join(''):`<div class="empty-mapping">${fields.length?'尚无参数契约，请回到第一步重新生成看板':'尚无参数契约；也未上传可映射的数据表字段'}</div>`;$$('[data-parameter]').forEach(select=>select.onchange=()=>{logic.mappings[select.dataset.parameter]=select.value;logic.sql=sqlFromTemplate(requirement,logic);logic.manual=false;logic.validation=null;save();renderDataWorkspace();renderMetrics()});const required=parameters.filter(p=>p.required),mapped=required.filter(p=>logic.mappings?.[p.key]).length;$('#mappingProgress').textContent=`${mapped} / ${required.length}`;$('#fieldValidation').textContent=required.length?`${mapped} / ${required.length} 个必填参数已映射`:'等待 DeepSeek 参数契约';$('#fieldValidationIcon').textContent=required.length&&mapped===required.length?'✓':'○';$('#logicStatusDot').classList.toggle('ok',Boolean(required.length&&mapped===required.length));$('#parameterStatus').textContent=!requirement?'等待参数':mapped===required.length?'映射完成':'待映射';$('#parameterStatus').classList.toggle('complete',Boolean(requirement&&mapped===required.length));if(!logic.sql)logic.sql=sqlFromTemplate(requirement,logic);$('#sqlEditor').value=logic.sql;$('#sqlDialect').value=logic.dialect||'SQL Server';$('#sqlLanguageLabel').textContent=`SQL · ${logic.dialect||'SQL Server'}`;$('#metricCode').value=metric.id;$('#metricChartType').value=metric.chart||'';$('#metricGrain').value=requirement?.grain||'待生成';$('#metricAggregation').value=requirement?.aggregation||'待生成';$('#metricLinkUrl').value=logic.linkUrl||'';renderSqlValidation(logic)}
function renderSqlValidation(logic){const current=logic?.validation&&logic.validation.sql===logic.sql?logic.validation:null;$('#sqlValidationIcon').textContent=current?.valid?'✓':'○';$('#sqlValidation').textContent=current?.valid?`验证通过 · ${(current.columns||[]).length} 个返回字段`:state.databaseMode==='online'?'等待在线验证':'数据库离线，无法验证 SQL'}
