function openMetric(id){const m=state.metrics.find(x=>x.id===id);$('#metricId').value=m?.id||'';$('#metricName').value=m?.name||'';$('#metricDesc').value=m?.desc||'';$('#metricChart').value=m?.chart||'指标卡';$('#metricIcon').value=m?.icon||'◇';$('#metricDialogTitle').textContent=m?'编辑指标':'新增指标';openModal('#metricModal')}
function deleteMetric(id){const m=state.metrics.find(x=>x.id===id);if(!m)return;state.metrics=state.metrics.filter(x=>x.id!==id);state.dashboardDesign=null;state.dataRequirements=(state.dataRequirements||[]).filter(r=>r.metricId!==id);if(state.dataLogic)delete state.dataLogic[id];if(activeMetric===id)activeMetric=state.metrics[0]?.id||'';save();renderMetrics();renderDashboard();renderDataWorkspace();toast(`已删除指标「${m.name}」`)}
