function displayValue(value){if(value==null)return '--';if(typeof value==='number')return Number.isInteger(value)?value.toLocaleString('zh-CN'):value.toLocaleString('zh-CN',{maximumFractionDigits:2});return String(value)}
function runtimeFromQuery(result){
  if(!result?.ok)return {displayValue:'--',labels:[],values:[],note:`取数失败：${result?.error||'未知错误'}`};
  const rows=result.rows||[],columns=result.columns?.length?result.columns:Object.keys(rows[0]||{});if(!rows.length)return {displayValue:'--',labels:[],values:[],note:'查询成功，但没有返回数据'};
  const numericColumn=columns.find(column=>rows.some(row=>typeof row[column]==='number'||(row[column]!==''&&Number.isFinite(Number(row[column])))))||columns.at(-1),labelColumn=columns.find(column=>column!==numericColumn)||columns[0];
  const values=rows.slice(0,8).map(row=>Number(row[numericColumn])).filter(Number.isFinite),labels=rows.slice(0,8).map((row,index)=>String(row[labelColumn]??`项${index+1}`));
  return {displayValue:displayValue(rows[0]?.[numericColumn]),labels,values,note:'在线数据库实时取数'};
}
function componentRuntime(component){if(state.previewDataMode!=='online')return component;const runtime=state.dashboardRuntimeData?.[component.metricId];return {...component,displayValue:runtime?.displayValue??'--',labels:runtime?.labels||[],values:runtime?.values||[],note:runtime?.note||'未配置可执行 SQL'}}
async function loadPreviewData(){
  if(state.databaseMode!=='online'){state.previewDataMode='offline';state.dashboardRuntimeData={};renderDashboard();toast('当前为离线模式，看板使用模拟数据');return}
  const metrics=state.metrics.map(metric=>({metricId:metric.id,sql:String(state.dataLogic?.[metric.id]?.sql||'').trim()})).filter(item=>item.sql&&!item.sql.startsWith('--')&&!item.sql.includes('{{'));
  state.previewDataMode='online';state.dashboardRuntimeData={};
  if(!metrics.length){renderDashboard();toast('在线模式下尚无可执行的指标 SQL');return}
  const response=await fetch('/api/execute-dashboard-sql',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({metrics})}),body=await response.json();if(!response.ok)throw new Error(body.error||'指标取数失败');
  for(const result of body.results||[])state.dashboardRuntimeData[result.metricId]=runtimeFromQuery(result);
  renderDashboard();const failures=(body.results||[]).filter(result=>!result.ok).length;toast(failures?`已完成在线取数，${failures} 个指标执行失败`:`已从数据库取得 ${body.results?.length||0} 个指标数据`);
}
const safeColor=(value,fallback)=>/^#[0-9a-f]{6}$/i.test(String(value||''))?value:fallback;
function componentChart(component,theme){const labels=(component.labels||[]).slice(0,8),values=(component.values||[]).slice(0,8).map(Number),accent=safeColor(theme.accent,'#176f52'),secondary=safeColor(theme.secondary,'#5178c5'),max=Math.max(...values,1);if(component.type==='kpi')return `<strong class="dash-value">${esc(component.displayValue||'--')}</strong><p class="dash-note">${esc(component.note)}</p>`;if(component.type==='bar')return `<div class="bar-chart">${values.map((value,i)=>`<span style="height:${Math.max(8,Math.round(value/max*92))}%;background:linear-gradient(${accent},${secondary})" data-label="${esc(labels[i]||`项${i+1}`)}"></span>`).join('')}</div><p class="dash-note">${esc(component.note)}</p>`;if(component.type==='line'){const points=values.map((value,i)=>`${values.length===1?300:Math.round(i*600/(values.length-1))},${Math.round(135-value/max*105)}`).join(' ');return `<svg class="line-chart" viewBox="0 0 600 150" preserveAspectRatio="none"><polyline points="${points}" fill="none" stroke="${accent}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><p class="dash-note">${esc(component.note)}</p>`}if(component.type==='donut'){const total=values.reduce((sum,value)=>sum+Math.max(value,0),0)||1,first=Math.round(Math.max(values[0]||0,0)/total*100);return `<div class="ai-donut" style="background:conic-gradient(${accent} 0 ${first}%,${secondary} ${first}% 100%)"><span>${first}%</span></div><p class="dash-note">${esc(component.note)}</p>`}return `<table class="dash-table">${labels.map((label,i)=>`<tr><td>${esc(label)}</td><td>${esc(values[i]??'--')}</td></tr>`).join('')}</table><p class="dash-note">${esc(component.note)}</p>`}
function renderDashboard(){const target=$('#dashboardPreview'),design=state.dashboardDesign;if(!design?.components?.length){target.classList.remove('generated');target.style.cssText='';$('#previewTitle').textContent=$('#projectName').value||'看板概念预览';$('#previewSubtitle').textContent=state.previewDataMode==='online'?'在线数据库实时数据':'离线模拟数据 · 非真实业务值';renderConceptDashboard();return}const theme=design.theme||{};target.classList.add('generated');target.style.setProperty('--dash-surface',safeColor(theme.surface,'#ffffff'));target.style.setProperty('--dash-text',safeColor(theme.text,'#17211e'));target.style.setProperty('--dash-muted',safeColor(theme.muted,'#68736d'));target.style.background=safeColor(theme.background,'#eef1ee');$('#previewTitle').textContent=design.title||$('#projectName').value;$('#previewSubtitle').textContent=state.previewDataMode==='online'?'在线数据库实时数据':'离线模拟数据 · 非真实业务值';target.innerHTML=design.components.map(raw=>{const component=componentRuntime(raw);return `<article class="dash-card" data-metric-id="${esc(component.metricId||'')}" style="--span:${Number(component.span)||6}"><h3>${esc(component.title)}</h3>${componentChart(component,theme)}</article>`}).join('');bindDashboardLinks()}
function save(){state.dashboardStyle=$('#dashboardStyle')?.value||state.dashboardStyle||'简约风格';state.styleNotes=$('#styleNotes')?.value||'';const data={name:$('#projectName').value,context:$('#businessContext').value,prompt:$('#promptText').value,...state,updatedAt:new Date().toISOString()};localStorage.setItem('dashboard-studio-project-v2',JSON.stringify(data));$('#savedState').textContent='✓ 已自动保存'}
