function renderSchemaAnalysis(){const analysis=state.schemaAnalysis,tables=analysis?.tables||[],relations=analysis?.relationships||[],previewFieldCount=tables.reduce((sum,table)=>sum+(table.fields?.length||0),0),tableCount=analysis?.stats?.tableCount??tables.length,fieldCount=analysis?.stats?.fieldCount??previewFieldCount;$('#schemaTableCount').textContent=tableCount;$('#schemaFieldCount').textContent=fieldCount;$('#schemaRelationCount').textContent=relations.length;$('#schemaList').innerHTML=tables.length?tables.slice(0,4).map(table=>`<span>${esc(table.name)} ${esc(table.businessName||'')}</span>`).join('')+(tables.length>4?'<button id="viewAllSchema">查看摘要 →</button>':''):'<span>尚未识别数据结构</span>';if($('#viewAllSchema'))$('#viewAllSchema').onclick=()=>toast(analysis?.truncated?`共 ${tableCount} 张表、${fieldCount} 个字段；页面仅保存轻量摘要，AI 按指标实时检索`:(relations.length?relations.map(r=>`${r.from} → ${r.to}`).join('；'):'暂未识别到表关联'));const fileBox=$('#fileAnalysis');if(fileBox)fileBox.innerHTML=tables.length?`<span>${esc(analysis.summary||`已识别 ${tables.length} 张业务表`)}</span>`+tables.slice(0,40).map(table=>`<article class="analysis-table"><b>${esc(table.businessName||table.name)} <em>${esc(table.name)}</em></b><small>${esc(table.description||'')} · ${(table.fields||[]).length} 个摘要字段 · ${(table.fields||[]).map(field=>`${esc(field.name)}（${esc(field.type)}）`).join('、')}</small></article>`).join(''):'<span>上传后将在这里显示模型识别结果</span>';renderSchemaDetails();renderDataWorkspace()}
