function renderDatabaseStatus(config=state.databaseMeta||{mode:'offline'}){state.databaseMeta=config;state.databaseMode=config.mode||'offline';$$('[data-db-mode]').forEach(button=>button.classList.toggle('active',button.dataset.dbMode===state.databaseMode));$('#databaseForm').classList.toggle('active',state.databaseMode==='online');$('#databaseOfflineNote').style.display=state.databaseMode==='offline'?'flex':'none';if(config.provider)$('#databaseProvider').value=config.provider;if(config.host!=null)$('#databaseHost').value=config.host;if(config.port)$('#databasePort').value=config.port;if(config.database!=null)$('#databaseName').value=config.database;if(config.schema!=null)$('#databaseSchema').value=config.schema;if(config.user!=null)$('#databaseUser').value=config.user;$('#databaseEncrypt').checked=Boolean(config.encrypt);$('#databaseTrustCert').checked=config.trustServerCertificate!==false;const status=$('#databaseConnectionStatus');if(state.databaseMode==='online'&&config.configured){status.innerHTML=`<span class="status-dot ok"></span><div><b>${esc(databaseLabels[config.provider]||config.provider)} 连接测试通过</b><small>${esc(config.host)}:${esc(config.port)} · 尚未主动读取结构</small></div>`}else status.innerHTML='<span class="status-dot"></span><div><b>尚未配置在线数据库</b><small>密码只保存在本机应用数据目录</small></div>';$('#databaseTableCount').textContent=config.stats?.tableCount??'--';$('#databaseFieldCount').textContent=config.stats?.fieldCount??'--';const syncButton=$('#syncDatabaseSchema');if(syncButton)syncButton.disabled=!(state.databaseMode==='online'&&config.configured);const syncHint=$('#schemaSyncHint');if(syncHint)syncHint.textContent=config.lastSyncedAt&&config.stats?`上次同步：${new Date(config.lastSyncedAt).toLocaleString()} · ${config.stats.tableCount} 张表 / ${config.stats.fieldCount} 个字段`:'连接测试通过后，可主动读取 CTL_TBL 与 FG_COLUMNS';save();workflow()}
