function fileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('文件读取失败'));reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.readAsDataURL(file)})}
async function analyzeDataFile(file){if(!file)return;if(!/\.(xlsx|csv)$/i.test(file.name)){toast('请选择 .xlsx 或 .csv 文件');return}if(file.size>8*1024*1024){toast('当前单个文件请控制在 8MB 以内');return}const box=$('#fileAnalysis');box.innerHTML='<span>正在提取工作表、字段和样例，并交给 DeepSeek 分析…</span>';try{const dataBase64=await fileAsBase64(file),res=await fetch('/api/analyze-data-source',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileName:file.name,mimeType:file.type,dataBase64,businessContext:$('#businessContext').value,model:state.deepseekModel})}),body=await res.json();if(!res.ok)throw new Error(body.error||'文件识别失败');state.schemaAnalysis=body.dataset;state.schemaReady=true;save();renderSchemaAnalysis();workflow();toast(`已识别 ${body.dataset.tables?.length||0} 张表和 ${body.fieldCount||0} 个字段`)}catch(error){box.innerHTML=`<span>识别失败：${esc(error.message)}</span>`;toast(`Excel 识别失败：${error.message}`)}}

function renderReferences(){const el=$('#referenceGallery');if(!state.references?.length){el.innerHTML='<span>尚未添加参考图</span>';return}el.innerHTML=state.references.map(r=>`<article class="reference-item"><img src="${r.dataUrl}" alt="${r.name}"><button data-remove-reference="${r.id}" title="删除">×</button><small>${r.name}</small></article>`).join('');$$('[data-remove-reference]').forEach(b=>b.onclick=()=>{state.references=state.references.filter(r=>r.id!==b.dataset.removeReference);save();renderReferences();toast('参考图已删除')})}
function compressImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('图片读取失败'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('图片格式不支持'));img.onload=()=>{const max=1280,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve({id:`ref_${Date.now()}_${Math.random().toString(36).slice(2,7)}`,name:file.name,type:'image/jpeg',dataUrl:canvas.toDataURL('image/jpeg',.76)})};img.src=reader.result};reader.readAsDataURL(file)})}
async function addReferenceFiles(files){const allowed=[...files].filter(f=>f.type.startsWith('image/')).slice(0,3-(state.references?.length||0));if(!allowed.length){toast(state.references?.length>=3?'最多添加 3 张参考图':'请选择 PNG、JPG 或 WebP 图片');return}try{const images=await Promise.all(allowed.map(compressImage));state.references=[...(state.references||[]),...images];save();renderReferences();toast(`已添加 ${images.length} 张参考图，生成时会交给 AI 分析`)}catch(error){toast(error.message)}}

async function generate(regenerate=false){
  workflow();const hasBusinessScene=Boolean($('#businessContext').value.trim());if(!hasBusinessScene){toast('请先填写业务场景与关注点');return}
  const btn=$('#generatePrototype');btn.disabled=true;btn.classList.add('loading');btn.querySelector('b').textContent=regenerate?'DeepSeek 正在重新设计…':'DeepSeek 正在生成方案…';
  const payload={project:$('#projectName').value,businessContext:$('#businessContext').value,prompt:$('#promptText').value,prototypeMode:!state.schemaReady,databaseSummary:state.schemaAnalysis?JSON.stringify(state.schemaAnalysis):state.schemaReady?'已提供数据结构，但尚无详细字段摘要':'尚未提供数据库结构，请先生成概念原型并明确标记待绑定字段',referenceImages:(state.references||[]).map(r=>({name:r.name,dataUrl:r.dataUrl})),existingMetrics:regenerate?state.metrics:[],authMode:state.authMode,model:state.authMode==='deepseek'?state.deepseekModel:state.customModel};
  let generated;
  try{const res=await fetch(state.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await res.json();if(!res.ok)throw new Error(typeof body.error==='string'?body.error:body.error?.message||'生成服务不可用');generated=body.dashboard?.metrics;if(!Array.isArray(generated)||!generated.length)throw new Error('模型未返回指标')}
  catch(error){btn.disabled=false;btn.classList.remove('loading');btn.querySelector('b').textContent=state.generated?'重新生成一版':'生成看板方案';toast(`AI 生成失败：${error.message}。可检查连接或载入示例方案`);return}
  state.metrics=generated.map((m,i)=>({id:m.id||`metric_${Date.now()}_${i}`,icon:m.icon||'◇',name:m.name,desc:m.desc||m.definition||'待补充计算口径',chart:m.chart||'指标卡',status:m.status||'draft'}));state.generated=true;state.dashboardDesign=null;state.dataRequirements=[];state.dataLogic={};
  const id=`v${Date.now()}`,version={id,label:`V${state.versions.length+1} · AI`,metrics:clone(state.metrics),createdAt:new Date().toISOString(),source:'ai'};state.versions.push(version);state.activeVersion=id;activeMetric=state.metrics[0]?.id||'';save();renderVersions();renderMetrics();renderDashboard();if(activeMetric)selectMetric(activeMetric);
  btn.disabled=false;btn.classList.remove('loading');btn.querySelector('b').textContent='重新生成一版';toast(`已生成 ${state.metrics.length} 个指标，保存为 ${version.label}`);workflow();
}
