$('#clearSchema').onclick=()=>{state.schemaReady=false;state.schemaAnalysis=null;$('#schemaFile').value='';$('#dataFile').value='';save();renderSchemaAnalysis();workflow();toast('数据库结构和 Excel 识别结果已清空')};
$('#loadDemo').onclick=()=>{state.schemaReady=true;state.schemaAnalysis={summary:'智慧园区演示数据结构',tables:[{name:'enterprise',businessName:'企业表',description:'园区入驻企业',rowCount:126,fields:[{name:'id',type:'主键'},{name:'name',type:'文本'},{name:'created_at',type:'日期'}]},{name:'building',businessName:'楼宇表',description:'楼宇与可租面积',rowCount:18,fields:[{name:'id',type:'主键'},{name:'name',type:'文本'},{name:'rentable_area',type:'数值'}]},{name:'contract',businessName:'租赁合同',description:'合同金额与租赁周期',rowCount:342,fields:[{name:'enterprise_id',type:'外键'},{name:'building_id',type:'外键'},{name:'total_amount',type:'金额'}]},{name:'payment',businessName:'收款记录',description:'应收与实收',rowCount:1086,fields:[{name:'contract_id',type:'外键'},{name:'receivable_amount',type:'金额'},{name:'paid_amount',type:'金额'}]}],relationships:[{from:'enterprise.id',to:'contract.enterprise_id'},{from:'building.id',to:'contract.building_id'},{from:'contract.id',to:'payment.contract_id'}]};save();renderSchemaAnalysis();workflow();toast('演示数据已载入，步骤 2 已完成')};$('#optimizePrompt').onclick=()=>{$('#promptText').value+='\n\n请为每个指标输出业务价值、计算口径、数据表与字段、筛选维度、建议图表，并标记数据质量风险。';save();workflow();toast('已补充字段约束与输出格式')};
$('#chooseReference').onclick=()=>$('#referenceFile').click();$('#referenceFile').onchange=e=>{addReferenceFiles(e.target.files);e.target.value=''};['dragenter','dragover'].forEach(evt=>$('#imageDrop').addEventListener(evt,e=>{e.preventDefault();$('#imageDrop').classList.add('drag')}));['dragleave','drop'].forEach(evt=>$('#imageDrop').addEventListener(evt,e=>{e.preventDefault();$('#imageDrop').classList.remove('drag');if(evt==='drop')addReferenceFiles(e.dataTransfer.files)}));
