$('#generateDashboardBtn').onclick=generateVisualDashboard;
$('#loadExamplePlan').onclick=()=>{state.metrics=localVariant();state.generated=true;state.dashboardDesign=null;state.dataRequirements=[];state.dataLogic={};const id=`v${Date.now()}`,version={id,label:`V${state.versions.length+1} · 示例`,metrics:clone(state.metrics),createdAt:new Date().toISOString(),source:'example'};state.versions.push(version);state.activeVersion=id;activeMetric=state.metrics[0]?.id||'';save();renderVersions();renderMetrics();renderDashboard();selectMetric(activeMetric);toast('已载入本地示例方案；请点击生成看板与取数参数')};
$('#metricForm').onsubmit=e=>{e.preventDefault();const id=$('#metricId').value||`custom_${Date.now()}`;const m={id,name:$('#metricName').value.trim(),desc:$('#metricDesc').value.trim(),chart:$('#metricChart').value,icon:$('#metricIcon').value||'◇',status:'draft'};const at=state.metrics.findIndex(x=>x.id===id);if(at>=0)state.metrics[at]=m;else state.metrics.push(m);state.generated=true;state.dashboardDesign=null;state.dataRequirements=(state.dataRequirements||[]).filter(r=>r.metricId!==id);if(state.dataLogic)delete state.dataLogic[id];save();renderMetrics();renderDashboard();renderDataWorkspace();closeModal('#metricModal');toast(at>=0?'指标已更新，请重新生成看板与参数':'指标已添加，请生成看板与参数')};$$('[data-metric-close]').forEach(x=>x.onclick=()=>closeModal('#metricModal'));
$('#previewBtn').onclick=async()=>{if(!workflow().unlocked){toast('请先填写业务场景描述');return}const button=$('#previewBtn'),original=button.textContent;button.disabled=true;button.textContent=state.databaseMode==='online'?'正在从数据库取数…':'正在准备模拟数据…';try{await loadPreviewData();openModal('#previewModal')}catch(error){toast(`看板取数失败：${error.message}`)}finally{button.disabled=false;button.textContent=original}};$$('[data-close]').forEach(x=>x.onclick=()=>closeModal('#previewModal'));$('#refreshDashboard').onclick=async()=>{try{await loadPreviewData()}catch(error){toast(`看板刷新失败：${error.message}`)}};
function showProvider(mode){state.authMode=mode;$$('.provider-option').forEach(x=>x.classList.toggle('active',x.dataset.provider===mode));$('#deepseekProvider').classList.toggle('active',mode==='deepseek');$('#apiProvider').classList.toggle('active',mode==='api')}
$('#openAiSettings').onclick=$('#settingsBtn').onclick=()=>{showProvider(state.authMode);openModal('#aiSettingsModal');checkAI()};$$('[data-ai-close]').forEach(x=>x.onclick=()=>closeModal('#aiSettingsModal'));$$('.provider-option').forEach(x=>x.onclick=()=>showProvider(x.dataset.provider));
async function persistDeepSeekKey(){state.deepseekModel=$('#deepseekModel').value;const res=await fetch('/api/settings/deepseek',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey:$('#deepseekApiKey').value.trim(),model:state.deepseekModel})});const body=await res.json();if(!res.ok)throw new Error(body.error||'密钥保存失败');$('#deepseekApiKey').value='';$('#deepseekKeyStatus').textContent=`密钥已安全保存在本机${body.keyHint?`（${body.keyHint}）`:''}`;$('#deepseekKeyStatus').classList.add('ready');return body}
$('#testAi').onclick=async()=>{try{$('#testAi').disabled=true;if(state.authMode==='deepseek'&&$('#deepseekApiKey').value.trim())await persistDeepSeekKey();const res=await fetch('/api/test-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:state.authMode})});const body=await res.json();if(!res.ok)throw new Error(body.error||'连接测试失败');save();await checkAI();toast('DeepSeek 密钥已保存，连接测试成功')}catch(error){toast(`连接测试失败：${error.message}`)}finally{$('#testAi').disabled=false}};
$('#saveAiSettings').onclick=async()=>{state.deepseekModel=$('#deepseekModel').value;state.apiBaseUrl=$('#apiBaseUrl').value.trim()||'https://api.example.com/v1';state.customModel=$('#customModel').value.trim()||'your-model-id';state.endpoint=$('#aiEndpoint').value.trim()||'/api/generate-dashboard';if(state.authMode==='deepseek'){try{await persistDeepSeekKey()}catch(error){toast(error.message);return}}save();closeModal('#aiSettingsModal');await checkAI();toast(`已保存 ${state.authMode==='deepseek'?'DeepSeek':'其他兼容模型'} 配置`)};$('#deepseekModel').value=state.deepseekModel;$('#apiBaseUrl').value=state.apiBaseUrl;$('#customModel').value=state.customModel;$('#aiEndpoint').value=state.endpoint;showProvider(state.authMode);
$('#initializeDataLogic').onclick=()=>{renderMetrics();renderDataWorkspace();toast(state.dataRequirements.length?`已同步当前方案的 ${state.metrics.length} 个指标和取数参数`:'当前指标已同步；请先在第一步生成看板以获取 DeepSeek 参数契约')};$('#sqlEditor').addEventListener('input',e=>{if(!activeMetric)return;const logic=getLogic(activeMetric);logic.sql=e.target.value;logic.manual=true;logic.validation=null;renderSqlValidation(logic);clearTimeout(window.sqlSaveTimer);window.sqlSaveTimer=setTimeout(save,350)});$('#resetSql').onclick=()=>{const requirement=getRequirement(activeMetric),logic=getLogic(activeMetric);logic.sql=sqlFromTemplate(requirement,logic);logic.manual=false;logic.validation=null;$('#sqlEditor').value=logic.sql;renderSqlValidation(logic);save();toast('已恢复 DeepSeek SQL 模板并应用当前字段映射')};$('#sqlDialect').onchange=e=>{const logic=getLogic(activeMetric);logic.dialect=e.target.value;logic.validation=null;$('#sqlLanguageLabel').textContent=`SQL · ${e.target.value}`;renderSqlValidation(logic);save()};$('#formatSql').onclick=()=>{const editor=$('#sqlEditor'),logic=getLogic(activeMetric);editor.value=editor.value.replace(/\s+(FROM|LEFT JOIN|RIGHT JOIN|INNER JOIN|WHERE|GROUP BY|ORDER BY|HAVING)\s+/gi,'\n$1 ').replace(/,\s*/g,',\n  ').trim();logic.sql=editor.value;logic.validation=null;renderSqlValidation(logic);save();toast('SQL 已做基础格式化')};
$('#metricLinkUrl').addEventListener('input',e=>{if(!activeMetric)return;getLogic(activeMetric).linkUrl=e.target.value.trim();clearTimeout(window.linkSaveTimer);window.linkSaveTimer=setTimeout(save,350)});$('#testMetricLink').onclick=()=>{if(activeMetric)openMetricLink(activeMetric)};
$('#aiCompleteSql').onclick=aiCompleteSql;
$('#validateSql').onclick=validateCurrentSql;
$('#copySql').onclick=()=>navigator.clipboard.writeText($('#sqlEditor').value).then(()=>toast('SQL 已复制'));$('#copyDeploy').onclick=()=>navigator.clipboard.writeText($('#deployCode').textContent).then(()=>toast('部署命令已复制'));$('#saveConfig').onclick=()=>{const logic=getLogic(activeMetric);if(logic.linkUrl&&!normalizedMetricLink(logic.linkUrl)){toast('跳转链接无效，仅支持 HTTP、HTTPS 或站内相对地址');$('#metricLinkUrl').focus();return}save();renderMetrics();renderDashboard();toast('当前指标的字段映射、SQL 和跳转链接已保存')};
$('#packageBtn').onclick=()=>{download('dashboard-deployment-manifest.json',JSON.stringify({'Dockerfile':'FROM nginx:alpine\nCOPY dist /usr/share/nginx/html'},null,2));toast('部署清单已生成')};$('#exportBtn').onclick=()=>{download('dashboard-studio-project.json',JSON.stringify({...state,name:$('#projectName').value,context:$('#businessContext').value,prompt:$('#promptText').value},null,2));toast('项目文件已导出')};
